/**
 * Trail Link Extension
 *
 * Shows a clickable trail link in the Pi footer for the current git branch.
 * Uses `entire trail list --json` to resolve the trail number, then constructs
 * a direct link to the trail detail page on entire.io.
 *
 * Also provides `/trail-watch` to subscribe to the current branch's active
 * Trail code-review stream and inject new review comments into the active Pi
 * session as user messages.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execSync, spawn, type ChildProcessWithoutNullStreams } from "node:child_process";

interface TrailInfo {
	number: number;
	title: string;
	branch: string;
	url: string;
}

interface TrailStreamEvent {
	event?: string;
	data?: {
		commentCount?: number;
		comment?: {
			id?: string;
			author?: string;
			body?: string;
			replies?: Array<{ id?: string; author?: string; body?: string }>;
		};
		commentId?: string;
	};
}

function getGitRemote(cwd: string): { org: string; repo: string } | null {
	try {
		const remote = execSync("git remote get-url origin", { cwd, encoding: "utf-8" }).trim();
		const match = remote.match(/github\.com[/:]([^/]+)\/([^/.]+)/);
		return match ? { org: match[1]!, repo: match[2]! } : null;
	} catch {
		return null;
	}
}

function getGitBranch(cwd: string): string | null {
	try {
		return execSync("git branch --show-current", { cwd, encoding: "utf-8" }).trim() || null;
	} catch {
		return null;
	}
}

type TrailLookup =
	| { status: "none" }
	| { status: "no-trail"; branch: string }
	| { status: "error"; message: string }
	| { status: "found"; trail: TrailInfo };

function getTrailForBranch(cwd: string): TrailLookup {
	const branch = getGitBranch(cwd);
	const remote = getGitRemote(cwd);
	if (!branch || !remote) return { status: "none" };

	try {
		const entireBin = process.env.ENTIRE_BIN || "entire";
		const json = execSync(`${entireBin} trail list --json`, {
			cwd,
			encoding: "utf-8",
			timeout: 10000,
		}).trim();

		const trails = JSON.parse(json) as Array<{ number?: number; branch?: string; title?: string }>;
		const trail = trails.find((t) => t.branch === branch);
		if (!trail?.number) return { status: "no-trail", branch };

		const slug = trail.title
			?.toLowerCase()
			.replace(/[^a-z0-9]+/g, "-")
			.replace(/^-+|-+$/g, "")
			.slice(0, 60);

		const url = `https://entire.io/gh/${remote.org}/${remote.repo}/trails/${trail.number}${slug ? `/${slug}` : ""}`;

		return { status: "found", trail: { number: trail.number, title: trail.title ?? branch, branch, url } };
	} catch (err) {
		const stderr = (err as { stderr?: Buffer | string }).stderr;
		const stderrText = typeof stderr === "string" ? stderr : stderr?.toString() ?? "";
		const message = (stderrText || (err as Error).message || "").trim().split("\n")[0] ?? "error";
		return { status: "error", message };
	}
}

function formatReviewComment(trail: TrailInfo, comment: NonNullable<TrailStreamEvent["data"]>["comment"]): string {
	const author = comment?.author || "unknown";
	const body = (comment?.body || "").trim();
	const replies = comment?.replies ?? [];
	const replyText = replies
		.filter((reply) => (reply.body || "").trim() !== "")
		.map((reply) => `\n\nReply from ${reply.author || "unknown"}:\n${(reply.body || "").trim()}`)
		.join("");

	return [
		`A new Entire Trail review comment arrived on trail #${trail.number} (${trail.title}).`,
		`URL: ${trail.url}`,
		`Author: ${author}`,
		"",
		body || "(empty comment)",
		replyText,
		"",
		"Please inspect the repository, determine whether code changes are needed, and address the review comment.",
	]
		.filter(Boolean)
		.join("\n");
}

export default function (pi: ExtensionAPI) {
	let watcher: ChildProcessWithoutNullStreams | undefined;
	let watchedTrail: TrailInfo | undefined;
	let watcherBuffer = "";
	let initialReplayRemaining = 0;
	let drainingInitialReplay = false;
	const seenCommentIds = new Set<string>();

	function update(cwd: string, ui: { theme: { fg: (c: string, t: string) => string }; setStatus: (id: string, text: string | undefined) => void }) {
		const result = getTrailForBranch(cwd);
		if (result.status === "none") {
			ui.setStatus("trail-link", undefined);
			return;
		}

		if (result.status === "no-trail") {
			ui.setStatus("trail-link", ui.theme.fg("dim", `no trail for ${result.branch}`));
			return;
		}

		if (result.status === "error") {
			ui.setStatus("trail-link", ui.theme.fg("dim", `trail: ${result.message}`));
			return;
		}

		const trail = result.trail;
		// OSC 8 hyperlink for clickable link in supported terminals
		const label = `#${trail.number} ${trail.title}`;
		const hyperlink = `\x1b]8;;${trail.url}\x07${label}\x1b]8;;\x07`;
		ui.setStatus("trail-link", ui.theme.fg("dim", "trail ") + ui.theme.fg("accent", hyperlink));
	}

	function stopWatcher() {
		if (!watcher) return;
		watcher.kill("SIGTERM");
		watcher = undefined;
		watchedTrail = undefined;
		watcherBuffer = "";
		initialReplayRemaining = 0;
		drainingInitialReplay = false;
		seenCommentIds.clear();
	}

	function handleStreamLine(line: string) {
		if (!line.trim()) return;

		let event: TrailStreamEvent;
		try {
			event = JSON.parse(line) as TrailStreamEvent;
		} catch {
			return;
		}

		if (event.event === "ready") {
			initialReplayRemaining = Math.max(0, event.data?.commentCount ?? 0);
			drainingInitialReplay = initialReplayRemaining > 0;
			return;
		}

		if (event.event !== "comment") return;
		const trail = watchedTrail;
		const comment = event.data?.comment;
		if (!trail || !comment) return;

		const id = comment.id || "";
		if (drainingInitialReplay) {
			if (id) seenCommentIds.add(id);
			initialReplayRemaining--;
			if (initialReplayRemaining <= 0) {
				drainingInitialReplay = false;
			}
			return;
		}

		// Avoid re-injecting if the stream reconnects and replays a comment we
		// already handled. Edits to an already-seen comment are ignored by design;
		// the goal is to alert on new review comments.
		if (id && seenCommentIds.has(id)) return;
		if (id) seenCommentIds.add(id);

		try {
			pi.sendUserMessage(formatReviewComment(trail, comment), { deliverAs: "steer" });
		} catch {
			try {
				pi.sendUserMessage(formatReviewComment(trail, comment));
			} catch {
				// Never crash Pi because the watcher failed to inject.
			}
		}
	}

	function startWatcher(cwd: string, ctx: { ui: { notify: (message: string, level?: string) => void; setStatus: (id: string, text: string | undefined) => void; theme: { fg: (c: string, t: string) => string } } }) {
		const result = getTrailForBranch(cwd);
		if (result.status !== "found") {
			const message = result.status === "no-trail" ? `No trail found for branch ${result.branch}.` : result.status === "error" ? `Cannot resolve trail: ${result.message}` : "Cannot resolve current branch/repo trail.";
			ctx.ui.notify(message, "error");
			return;
		}

		stopWatcher();
		watchedTrail = result.trail;
		const entireBin = process.env.ENTIRE_BIN || "entire";
		watcher = spawn(entireBin, ["trail", "watch", String(result.trail.number), "--json"], {
			cwd,
			env: process.env,
			stdio: ["ignore", "pipe", "pipe"],
		});

		ctx.ui.notify(`Watching trail #${result.trail.number} review comments.`, "info");
		ctx.ui.setStatus("trail-watch", ctx.ui.theme.fg("accent", `watching #${result.trail.number}`));

		watcher.stdout.on("data", (chunk: Buffer) => {
			watcherBuffer += chunk.toString("utf8");
			let idx = watcherBuffer.indexOf("\n");
			while (idx >= 0) {
				const line = watcherBuffer.slice(0, idx);
				watcherBuffer = watcherBuffer.slice(idx + 1);
				handleStreamLine(line);
				idx = watcherBuffer.indexOf("\n");
			}
		});

		watcher.stderr.on("data", (chunk: Buffer) => {
			const text = chunk.toString("utf8").trim();
			if (!text) return;
			if (text.includes("Watching trail") || text.includes("server requested reconnect")) return;
			ctx.ui.setStatus("trail-watch", ctx.ui.theme.fg("dim", `trail watch: ${text.split("\n")[0]}`));
		});

		watcher.on("exit", (code, signal) => {
			if (!watchedTrail) return;
			const exitedTrail = watchedTrail;
			watcher = undefined;
			watchedTrail = undefined;
			ctx.ui.setStatus("trail-watch", undefined);
			if (code !== 0 && signal !== "SIGTERM") {
				ctx.ui.notify(`Trail watcher for #${exitedTrail.number} stopped (exit ${code ?? signal ?? "unknown"}).`, "error");
			}
		});
	}

	pi.registerCommand("trail-watch", {
		description: "Watch active Entire trail review comments and send them to this Pi session",
		handler: async (args: string, ctx: any) => {
			const action = args.trim();
			if (action === "stop" || action === "off") {
				stopWatcher();
				ctx.ui.setStatus("trail-watch", undefined);
				ctx.ui.notify("Stopped trail review watcher.", "info");
				return;
			}
			startWatcher(ctx.cwd, ctx);
		},
	});

	pi.on("session_start", (_event, ctx) => {
		update(ctx.cwd, ctx.ui);
	});

	pi.on("agent_end", (_event, ctx) => {
		update(ctx.cwd, ctx.ui);
	});

	pi.on("session_shutdown", () => {
		stopWatcher();
	});
}

